static std::string matrix_json_quote(const std::string&s){std::ostringstream o;o<<'"';for(unsigned char c:s){if(c=='"'||c=='\\')o<<'\\'<<char(c);else if(c<32)o<<"\\u00"<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);else o<<char(c);}return o.str()+'"';}
static std::string hash(const void*p,uint64_t n){CC_SHA256_CTX s;CC_SHA256_Init(&s);auto b=static_cast<const unsigned char*>(p);while(n){auto k=CC_LONG(std::min<uint64_t>(n,1ull<<30));CC_SHA256_Update(&s,b,k);b+=k;n-=k;}unsigned char out[32];CC_SHA256_Final(out,&s);std::ostringstream o;for(auto c:out)o<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(c);return o.str();}
static void dump(const std::string&path,const void*p,uint64_t n){int fd=open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600);if(fd<0)throw std::runtime_error("exclusive file creation: "+path);auto b=static_cast<const char*>(p);while(n){ssize_t x=write(fd,b,size_t(std::min<uint64_t>(n,1ull<<30)));if(x<0&&errno==EINTR)continue;if(x<=0){close(fd);throw std::runtime_error("write failure");}n-=x;b+=x;}if(fsync(fd)){close(fd);throw std::runtime_error("fsync failure");}close(fd);}
static void emit(const std::string&s){std::cout<<s<<std::endl;if(!std::cout)throw std::runtime_error("stdout failure");}
static uint64_t parse_uint(const std::string&s){if(s.empty()||s.size()>20||(s.size()>1&&s[0]=='0'))throw std::runtime_error("invalid integer");uint64_t x=0;for(char c:s){if(c<'0'||c>'9'||x>(UINT64_MAX-unsigned(c-'0'))/10)throw std::runtime_error("integer overflow");x=x*10+unsigned(c-'0');}return x;}
static std::string image_record(const void*p){Dl_info d{};if(!p||!dladdr(p,&d))throw std::runtime_error("unresolved image");std::ostringstream o;o<<"{\"address\":"<<uintptr_t(p)<<",\"image_base\":"<<uintptr_t(d.dli_fbase)<<",\"image\":"<<matrix_json_quote(d.dli_fname)<<",\"symbol\":"<<matrix_json_quote(d.dli_sname?d.dli_sname:"")<<",\"uuid\":";std::string uuid;auto h=static_cast<const mach_header_64*>(d.dli_fbase);if(h->magic==MH_MAGIC_64){auto c=reinterpret_cast<const load_command*>(h+1);for(uint32_t i=0;i<h->ncmds;i++){if(c->cmdsize<8)break;if(c->cmd==LC_UUID){auto u=reinterpret_cast<const uuid_command*>(c);std::ostringstream t;for(auto b:u->uuid)t<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(b);uuid=t.str();}c=reinterpret_cast<const load_command*>(reinterpret_cast<const char*>(c)+c->cmdsize);}}o<<matrix_json_quote(uuid)<<'}';return o.str();}
static std::string images(){std::ostringstream o;o<<'[';for(uint32_t i=0;i<_dyld_image_count();i++){if(i)o<<',';o<<image_record(_dyld_get_image_header(i));}return o.str()+']';}
