 Create create=nullptr;Run run=nullptr,prepared=nullptr;Destroy destroy=nullptr;int(*prepare)(mp5_context*)=nullptr;const char*(*native_name)(const mp5_context*)=nullptr;const void*(*native_address)(const mp5_context*)=nullptr;int(*thread)(const mp5_context*)=nullptr;int(*jit)(const mp5_context*,mp5_prepared_jit_info*)=nullptr;int(*copy)(const mp5_context*,void*,uint64_t,uint64_t*)=nullptr;
