static std::string jit_record(Backend&b,mp5_context*c,const std::string&prefix){if(!b.jit)return "null";mp5_prepared_jit_info j{};if(b.jit(c,&j))throw std::runtime_error("JIT observation failure");uint64_t n=0;if(b.copy(c,nullptr,0,&n)||n>131072)throw std::runtime_error("JIT code bound");std::vector<unsigned char>code(n);uint64_t actual=0;if(n&&b.copy(c,code.data(),n,&actual))throw std::runtime_error("JIT copy failure");if(n!=actual||n!=j.code_bytes)throw std::runtime_error("JIT length identity");if(n)dump(prefix+".code.bin",code.data(),n);std::ostringstream o;o<<"{\"generation_requests\":"<<j.generation_requests<<",\"cache_lookups\":"<<j.cache_lookups<<",\"invocations\":"<<j.invocations<<",\"code_bytes\":"<<n<<",\"code_sha256\":"<<matrix_json_quote(hash(code.data(),n))<<",\"target_arch_id\":"<<j.target_arch_id<<",\"generated\":"<<j.generated<<",\"runtime_address\":"<<uintptr_t(b.native_address?b.native_address(c):nullptr)<<'}';return o.str();}
static void clock_identity(const std::string&expected){matrix_clock_pointer=dlsym(RTLD_DEFAULT,"mach_absolute_time");if(!matrix_clock_pointer||hash(matrix_clock_pointer,144)!=expected)throw std::runtime_error("clock implementation is not audited: expected SHA256 for first 144 mach_absolute_time bytes differs");auto selector=*reinterpret_cast<const volatile unsigned char*>(uintptr_t(0xfffffc090ull));if(!selector)throw std::runtime_error("clock zero selector unsupported");}
static void require_registry_member(uint64_t m,uint64_t n,uint64_t k){if(!mp5_registry::allowed(static_cast<int64_t>(m),static_cast<int64_t>(n),static_cast<int64_t>(k)))throw std::runtime_error("MATRIX_NONMEMBER");}
